if (this.featureToggles.enableApplyVoucherEndpoint) {
  const applyVoucherUrl = this.getApplyCartVoucherEndpoint(userId, cartId);
  const body = { voucherId };
  return this.http.post(applyVoucherUrl, body, { headers }).pipe(
    catchError((error: any) => {
      throw tryNormalizeHttpError(error, this.logger);
    }),
    this.converter.pipeable(CART_VOUCHER_NORMALIZER)
  );
}

  this.featureToggles.mergeGuestCartOnCodeFlowLogin &&
  this.activeCartStatePersistenceService.readGuestCartState()
) {
  // Authorization-code flow: the SPA was re-bootstrapped on login, so the
  // in-memory guest cart (and thus `isGuestCart()`) is gone. Fall back to
  // the entries we persisted before the redirect.
  this.guestCartMerge(cartId);
}

if (this.featureToggles.searchBoxEmptyQueryResultsPanel) {
  if (this.currentQueryLength === 0) {
    return this.hasOuterSearches();
  }
  return this.hasOccResults(results) || this.hasOuterSearches();
}

if (this.featureToggles.searchBoxEmptyQueryResultsPanel) {
  const query = this.searchInputEl?.nativeElement?.value ?? '';
  if (!query.trim()) {
    return false;
  }
}

